"""GRPO shape: cr_music — Story → Screenplay → KeyFrame → Video → Music → AudioMix → Compositor.

50 short-brief samples (target_n=60; remaining 10 go in shape_cr_music_long.py).
Cinematic mini-drama WITH BGM, NO ambient sound. Topics span genre/era/protagonist/
score combinations distinct from SFT shape_cr_music.py. Rationale style mirrors SFT
cr_music pattern: long flow narrative naming all 7 chain agents + standard reject list.
"""
from __future__ import annotations


_REJECT = (
    "Reject AmbienceAgent, Transcription/Translation, VideoAnalysis/IntakeVideo/"
    "StyleTransfer/VideoExtend/Highlight, Narration/Illustration/Narrator."
)


def _make(theme, arc, scenes, settings, aesthetic, bgm, score):
    """Return rationale + intents for one cr_music sample (chain length 7)."""
    return {
        "rationale": (
            f"{theme} mini-drama from a text brief + {bgm} BGM. StoryAgent drafts the "
            f"{arc} blueprint. ScreenplayAgent breaks it into {scenes} scenes. "
            f"KeyFrameAgent plans keyframes for the {settings} settings from text alone. "
            f"VideoAgent assembles the multi-shot film. MusicAgent composes the {score} "
            f"score. AudioMixAgent layers it under the dialogue+foley. CompositorAgent "
            "muxes the final mp4. " + _REJECT
        ),
        "intents": [
            f"Draft the {theme} story blueprint — {arc} arc.",
            f"Decompose the {arc} arc into {scenes} scenes.",
            f"Plan keyframes for the {settings} settings; text-only generation, no reference images supplied.",
            f"Render per-shot clips preserving {aesthetic} visual continuity.",
            f"Compose the {bgm} BGM the user requested, matching the {aesthetic} register.",
            f"Layer the {bgm} BGM under the clip's baked dialogue+foley track into one final mixed wav.",
            f"Composite the final {aesthetic} mini-drama mp4 with mixed audio and inter-shot transitions.",
        ],
    }


